import sys

def get_divisors(x):
    divisors = set()
    i = 1
    while i * i <= x:
        if x % i == 0:
            divisors.add(i)
            divisors.add(x // i)
        i += 1
    return divisors

def main():
    N = int(sys.stdin.readline())
    if N == 1:
        print(0)
        return

    # Case 2a: divisors of N-1 >= 2
    divisors_n_minus_1 = get_divisors(N - 1)
    count_2a = 0
    for d in divisors_n_minus_1:
        if d >= 2:
            count_2a += 1

    # Case 2b: divisors of N >= 2 that satisfy R mod K == 1
    divisors_n = get_divisors(N)
    count_2b = 0
    for K in divisors_n:
        if K < 2:
            continue
        temp = N
        while temp % K == 0:
            temp //= K
        R = temp
        if R % K == 1:
            count_2b += 1

    print(count_2a + count_2b)

