def factorize(x):
    factors = {}
    i = 2
    while i * i <= x:
        while x % i == 0:
            factors[i] = factors.get(i, 0) + 1
            x = x // i
        i += 1
    if x > 1:
        factors[x] = 1
    return factors

def generate_divisors(factors):
    divisors = [1]
    for p, exp in factors.items():
        temp = []
        for d in divisors:
            current = d
            for e in range(1, exp + 1):
                current *= p
                temp.append(current)
        divisors += temp
    return divisors

def main():
    import sys
    N = int(sys.stdin.readline())

    # Part A: Count divisors of N-1 >= 2
    x = N - 1
    if x == 0:
        part_A = 0
    else:
        factors_x = factorize(x)
        divisors_x = generate_divisors(factors_x)
        part_A = sum(1 for d in divisors_x if d >= 2)

    # Part B: Count valid divisors of N >= 2
    factors_N = factorize(N)
    divisors_N = generate_divisors(factors_N)
    count_B = 0

    for K in divisors_N:
        if K < 2:
            continue
        temp = N
        while temp % K == 0:
            temp = temp // K
        if temp % K == 1:
            count_B += 1

    print(part_A + count_B)

