import sys
from functools import lru_cache

def main():
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    A = list(map(int, input[2:2+N]))

    max_bit = 40  # since K can be up to 1e12, which is 40 bits.
    count_ones = [0] * (max_bit + 1)
    for a in A:
        for bit in range(max_bit + 1):
            if a & (1 << bit):
                count_ones[bit] += 1
    count_zeros = [N - cnt for cnt in count_ones]

    @lru_cache(maxsize=None)
    def dfs(bit, tight):
        if bit == -1:
            return 0
        if tight:
            current_k_bit = (K >> bit) & 1
            if current_k_bit == 1:
                possible_bits = [0, 1]
            else:
                possible_bits = [0]
        else:
            possible_bits = [0, 1]
        max_sum = 0
        for b in possible_bits:
            if tight:
                new_tight = (b == current_k_bit)
            else:
                new_tight = False
            if b == 0:
                contrib = count_ones[bit] * (1 << bit)
            else:
                contrib = count_zeros[bit] * (1 << bit)
            res = contrib + dfs(bit - 1, new_tight)
            if res > max_sum:
                max_sum = res
        return max_sum

    result = dfs(max_bit, True)
    print(result)

