    for i in range(max_bit + 1):
        for a in A:
            if (a >> i) & 1:
                cnt_1[i] += 1

    tight_max = 0
    not_tight_max = float('-inf')

    for i in reversed(range(max_bit + 1)):
        current_k_bit = (K >> i) & 1
        new_tight = float('-inf')
        new_not_tight = float('-inf')

        # Process transitions from tight state
        for b in [0, 1]:
            if b < current_k_bit:
                contribution = (cnt_1[i] if b == 0 else (N - cnt_1[i])) * (1 << i)
                if new_not_tight < tight_max + contribution:
                    new_not_tight = tight_max + contribution
            elif b == current_k_bit:
                contribution = (cnt_1[i] if b == 0 else (N - cnt_1[i])) * (1 << i)
                if new_tight < tight_max + contribution:
                    new_tight = tight_max + contribution

        # Process transitions from not_tight state
        for b in [0, 1]:
            contribution = (cnt_1[i] if b == 0 else (N - cnt_1[i])) * (1 << i)
            if new_not_tight < not_tight_max + contribution:
                new_not_tight = not_tight_max + contribution

        tight_max, not_tight_max = new_tight, new_not_tight

    print(max(tight_max, not_tight_max))

